function t(){const e=window.getSelection();return e?e.toString().trim():""}chrome.runtime.onMessage.addListener((e,o,n)=>{if(e.type==="GET_CURRENT_SELECTION"){const i=t();n({type:"CURRENT_SELECTION_RESPONSE",text:i})}return!0});document.addEventListener("selectionchange",()=>{const e=t();e.length>0&&(clearTimeout(window.selectionTimeout),window.selectionTimeout=setTimeout(()=>{chrome.runtime.sendMessage({type:"SELECTION_CHANGED",text:e}).catch(()=>{})},500))});
